using System;using System.Reflection;using System.Runtime.InteropServices;using System.Collections;
class CheckPaused { [STAThread] static int Main(string[] args){var a=Assembly.LoadFrom(args[0]);var t=a.GetType("PptEase.Host.Connect");var host=Activator.CreateInstance(t);object app=Marshal.GetActiveObject("PowerPoint.Application");t.GetField("app",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(host,app);object[] values={null,false,0d};var shapes=(ICollection)t.GetMethod("ShaderSceneShapes",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(host,values);Console.WriteLine("Scene="+values[0]+" Presenting="+values[1]+" Shapes="+shapes.Count);return shapes.Count>0&&(bool)values[1]?0:1;} }
